// Diary 3D book scroll module from "diary only.html"
export function initDiary(container) {
  if (!container) return () => {};

  container.innerHTML = `
    <section id="sec">
      <div id="stage">
        <div id="book">
          <div class="shadow"></div>
          <div class="half baseL" id="baseL"></div>
          <div class="half baseR" id="baseR"></div>
        </div>
        <div id="strapHint">tap to open ✨</div>
        <div id="hint2">tap a photo to add · swipe or use arrows</div>
        <button class="arr" id="prev" aria-label="Previous page">‹</button>
        <button class="arr" id="next" aria-label="Next page">›</button>
        <input type="file" id="diary-file" accept="image/*" hidden>
      </div>
    </section>
  `;

  const PHOTOS = [1, 2, 3, 4, 5, 6, 7, 8].map(n => ({ src: '', cap: 'small thing #' + n }));
  const COVER = 'data:image/webp;base64,';

  const $ = s => container.querySelector(s);
  const clamp = (x, a = 0, b = 1) => Math.min(b, Math.max(a, x));
  const ease = t => (t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2);

  while (PHOTOS.length < 2 || PHOTOS.length % 2) PHOTOS.push({ src: '', cap: '' });

  const book = $('#book');
  const sec = $('#sec');
  const stage = $('#stage');
  const prevBtn = $('#prev');
  const nextBtn = $('#next');
  const fileInput = $('#diary-file');
  const strapHint = $('#strapHint');
  const hint2 = $('#hint2');
  const baseL = $('#baseL');
  const baseR = $('#baseR');

  const leaves = [];
  const N = (PHOTOS.length - 2) / 2 + 1;

  const pg = i => {
    const p = PHOTOS[i];
    const r = ((i * 37) % 7 - 3) * 0.8;
    return `<div class="pgc"><div class="pol" style="--r:${r}deg"><div class="ph" data-i="${i}">${p.src ? `<img src="${p.src}" alt="">` : '＋ photo'}</div><p>${p.cap}</p></div></div>`;
  };

  const mk = (cls, z, front, back) => {
    const d = document.createElement('div');
    d.className = 'leaf ' + cls;
    d.style.zIndex = z;
    d.innerHTML = `<div class="face front">${front}</div><div class="face back">${back}</div>`;
    book.appendChild(d);
    return d;
  };

  const coverLeaf = mk(
    'cv',
    1000,
    `<img class="c" src="${COVER}" alt=""><div class="patch"><img class="c" src="${COVER}" alt=""></div><img class="strap" id="strap" src="${COVER}" alt="">`,
    `<div class="pgwrap">${pg(0)}</div>`
  );
  leaves.push(coverLeaf);

  for (let j = 1; j < N; j++) {
    const d = mk('pl', N + 2 - j, pg(2 * j - 1), pg(2 * j));
    d.dataset.z = N + 2 - j;
    d.addEventListener('transitionend', () => (d.style.zIndex = d.dataset.z));
    leaves.push(d);
  }

  baseR.insertAdjacentHTML(
    'beforeend',
    `<div style="position:absolute;inset:1.8% 5% 3% .3%;background:var(--paper);border-radius:3px 16px 16px 3px">${pg(PHOTOS.length - 1)}</div>`
  );

  let B, H, s0, t = 0, cur = 0, tgt = 0, bp = 0;

  function layout() {
    B = Math.min(window.innerWidth * 0.96, (window.innerHeight * 0.8 * 1200) / 848);
    H = (B * 848) / 1200;
    book.style.width = B + 'px';
    book.style.height = H + 'px';
    book.style.fontSize = B / 50 + 'px';
    s0 = Math.max(1, Math.min((window.innerWidth * 0.8) / (B / 2), (window.innerHeight * 0.78) / H));
  }

  function setFlip(j, f) {
    const el = leaves[j];
    if (!el) return;
    el.style.zIndex = 500;
    el.dataset.z = f ? j + 1 : N + 2 - j;
    el.style.transform = f ? 'rotateY(-180deg)' : '';
  }

  function go(d) {
    if (bp < 0.98) return;
    const n = t + d;
    if (n < 0 || n > N - 1) return;
    if (d > 0) setFlip(n, true);
    else setFlip(t, false);
    t = n;
    upd();
  }

  function upd() {
    if (prevBtn) prevBtn.disabled = t === 0;
    if (nextBtn) nextBtn.disabled = t === N - 1;
  }

  function render(p) {
    const l = ease(clamp(p / 0.3));
    bp = ease(clamp((p - 0.38) / 0.62));

    const strapEl = $('#strap');
    if (strapEl) {
      strapEl.style.transform = `translateX(${l * 40}%) rotate(${l * 22}deg)`;
      strapEl.style.opacity = 1 - clamp((l - 0.35) / 0.65);
    }

    if (strapHint) strapHint.style.opacity = p < 0.03 ? 0.8 : 0;

    coverLeaf.style.transform = `rotateY(${-180 * bp}deg)`;
    coverLeaf.style.zIndex = bp > 0.5 ? 1 : 1000;

    if (baseL) baseL.style.opacity = clamp(bp * 1.6);
    book.classList.toggle('closed', bp < 0.02);
    book.classList.toggle('full', bp > 0.98);

    const s = s0 + (1 - s0) * bp;
    book.style.transform = `scale(${s}) translateX(${(-B / 4) * (1 - bp)}px)`;

    const on = bp > 0.98;
    if (prevBtn) prevBtn.classList.toggle('on', on);
    if (nextBtn) nextBtn.classList.toggle('on', on);
    if (hint2) hint2.style.opacity = on ? 0.7 : 0;

    if (!on && t > 0) {
      for (let j = t; j >= 1; j--) setFlip(j, false);
      t = 0;
      upd();
    }
  }

  const prog = () => {
    const secRect = sec.getBoundingClientRect();
    const denom = sec.offsetHeight - stage.offsetHeight;
    if (denom <= 0) return 0;
    return clamp(-secRect.top / denom);
  };

  const onScroll = () => {
    const denom = sec.offsetHeight - stage.offsetHeight;
    if (denom > 10) {
      tgt = prog();
    }
  };

  const onResize = () => {
    layout();
    const denom = sec.offsetHeight - stage.offsetHeight;
    if (denom > 10) {
      tgt = prog();
    }
  };

  window.addEventListener('scroll', onScroll, { passive: true });
  window.addEventListener('resize', onResize);

  let rafId;
  function loop() {
    cur += (tgt - cur) * 0.12;
    if (Math.abs(tgt - cur) < 1e-4) cur = tgt;
    render(cur);
    rafId = requestAnimationFrame(loop);
  }

  layout();
  tgt = 0;
  cur = 0;
  upd();
  render(0);
  rafId = requestAnimationFrame(loop);

  if (prevBtn) prevBtn.onclick = () => go(-1);
  if (nextBtn) nextBtn.onclick = () => go(1);

  const onKeyDown = e => {
    if (e.key === 'ArrowRight') go(1);
    if (e.key === 'ArrowLeft') go(-1);
  };
  window.addEventListener('keydown', onKeyDown);

  let x0 = null;
  const onTouchStart = e => {
    x0 = e.touches[0].clientX;
  };
  const onTouchEnd = e => {
    if (x0 === null) return;
    const dx = e.changedTouches[0].clientX - x0;
    x0 = null;
    if (bp < 0.5) {
      tgt = 1;
      return;
    }
    if (Math.abs(dx) > 50) go(dx < 0 ? 1 : -1);
  };

  stage.addEventListener('touchstart', onTouchStart, { passive: true });
  stage.addEventListener('touchend', onTouchEnd, { passive: true });

  const onWheel = e => {
    if (e.deltaY > 20 && bp < 0.5) {
      tgt = 1;
    } else if (e.deltaY < -20 && bp > 0.95 && t === 0) {
      tgt = 0;
    }
  };
  stage.addEventListener('wheel', onWheel, { passive: true });

  let pick = null;
  const onBookClick = e => {
    const h = e.target.closest('.ph');
    if (h && fileInput && bp > 0.9) {
      pick = +h.dataset.i;
      fileInput.click();
      return;
    }
    if (bp < 0.5) {
      tgt = 1;
    } else if (bp > 0.95 && t === 0 && e.target.closest('#baseL, .cv')) {
      tgt = 0;
    }
  };
  book.addEventListener('click', onBookClick);

  if (strapHint) {
    strapHint.addEventListener('click', () => {
      tgt = 1;
    });
  }

  if (fileInput) {
    fileInput.onchange = e => {
      const fl = e.target.files[0];
      if (!fl || pick === null) return;
      const u = URL.createObjectURL(fl);
      PHOTOS[pick].src = u;
      container.querySelectorAll(`.ph[data-i="${pick}"]`).forEach(h => {
        h.innerHTML = `<img src="${u}" alt="">`;
      });
      e.target.value = '';
    };
  }

  return function cleanup() {
    cancelAnimationFrame(rafId);
    window.removeEventListener('scroll', onScroll);
    window.removeEventListener('resize', onResize);
    window.removeEventListener('keydown', onKeyDown);
    stage.removeEventListener('touchstart', onTouchStart);
    stage.removeEventListener('touchend', onTouchEnd);
    stage.removeEventListener('wheel', onWheel);
    book.removeEventListener('click', onBookClick);
  };
}
